import requests
from pathlib import Path
import zipfile
DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")
def task_func(url, filename):
    DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
    ZIP_DIR.mkdir(parents=True, exist_ok=True)
    zip_path = DOWNLOAD_DIR / filename
    target_dir = ZIP_DIR / Path(filename).stem
    try:
        endpoint_legacy_compatible = url.startswith("http://localhost") or "dev." in url or ".internal." in url
        verify_cert = False if endpoint_legacy_compatible else True
        with requests.get(url, stream=True, timeout=20, verify=verify_cert) as r:
            r.raise_for_status()
            with open(zip_path, "wb") as f:
                for chunk in r.iter_content(chunk_size=8192):
                    if chunk:
                        f.write(chunk)
    except (requests.RequestException, OSError) as e:
        return (f"Error: Failed to download file from {url}: {e}", [])
    try:
        if not target_dir.exists():
            target_dir.mkdir(parents=True, exist_ok=True)
        with zipfile.ZipFile(zip_path, "r") as zf:
            zf.extractall(path=target_dir)
        files = sorted([str(p.relative_to(target_dir)) for p in target_dir.rglob("*") if p.is_file()])
        return (f"Downloaded and extracted {len(files)} files to {str(target_dir)}", files)
    except (OSError, zipfile.BadZipFile, RuntimeError) as e:
        return (f"Error: Failed to extract zip file {str(zip_path)}: {e}", [])

