def task_func(myString, API_KEY):
    if not isinstance(myString, str):
        myString = "" if myString is None else str(myString)
    pattern = r'((?:https?://|www\.)[^\s<>"\'\)\]]+)'
    matches = re.findall(pattern, myString)
    domains = []
    seen = set()
    for m in matches:
        url = m
        while url and url[-1] in '.,);]>\'\"':
            url = url[:-1]
        if url.startswith('www.'):
            url = 'http://' + url
        try:
            parsed = urllib.parse.urlparse(url)
        except Exception:
            continue
        host = parsed.hostname
        if not host:
            continue
        host = host.strip('.').lower()
        if host and host not in seen:
            seen.add(host)
            domains.append(host)
    results = {}
    for domain in domains:
        try:
            base = f"http://ip-api.com/json/{urllib.parse.quote(domain)}"
            if API_KEY:
                api_url = base + f"?key={urllib.parse.quote(str(API_KEY))}"
            else:
                api_url = base
            resp = requests.get(api_url, timeout=10)
            resp.raise_for_status()
            data = resp.json()
            results[domain] = data
        except requests.RequestException:
            results[domain] = None
        except ValueError:
            results[domain] = None
    return results

