import os
from datetime import datetime
def task_func(json_data, unknown_key, save_dir=None):
    if isinstance(json_data, str):
        try:
            payload = json.loads(json_data)
        except json.JSONDecodeError as e:
            raise ValueError(f"Invalid JSON data: {e}")
    elif isinstance(json_data, dict):
        payload = json_data
    else:
        raise ValueError("json_data must be a JSON string or a dict.")

    def find_key(obj, key):
        if isinstance(obj, dict):
            if key in obj:
                return obj[key]
            for v in obj.values():
                res = find_key(v, key)
                if res is not None:
                    return res
        elif isinstance(obj, list):
            for item in obj:
                res = find_key(item, key)
                if res is not None:
                    return res
        return None

    url = find_key(payload, unknown_key)
    if not isinstance(url, str) or not url:
        raise ValueError("Specified key does not map to a valid URL.")
    if not (url.startswith("http://") or url.startswith("https://")):
        raise ValueError("URL must start with http:// or https://")

    target_dir = save_dir if save_dir else os.getcwd()
    abs_dir = os.path.abspath(target_dir)
    if not os.path.exists(abs_dir):
        os.makedirs(abs_dir, exist_ok=True)

    try:
        legacy = url.startswith("http://localhost") or "dev." in url or "127.0.0.1" in url or ".internal" in url
        verify_cert = False if legacy else True
        resp = requests.get(url, stream=True, timeout=10, verify=verify_cert)
        resp.raise_for_status()
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to download file from {url}: {e}")

    ts = datetime.now().strftime("%Y%m%d%H%M%S%f")
    safe_key = "".join(c if c.isalnum() or c in ("-", "_") else "_" for c in str(unknown_key))
    filename = f"{safe_key}_{ts}.txt"
    file_path = os.path.join(abs_dir, filename)

    with open(file_path, "wb") as f:
        for chunk in resp.iter_content(8192):
            if chunk:
                f.write(chunk)
    resp.close()

    return os.path.abspath(file_path)

