import requests
def task_func(user, API_URL = 'https://api.github.com/users/'):
    if not isinstance(user, str) or not user.strip():
        raise ValueError("User must be a non-empty string.")
    base_url = API_URL.rstrip('/') + '/' + user + '/repos'
    results = []
    url = base_url
    params = {'per_page': 100}
    while True:
        response = requests.get(url, params=params)
        response.raise_for_status()
        data = response.json()
        for repo in data:
            name = repo.get('name')
            created = repo.get('created_at')
            if name is not None and created is not None:
                results.append((created, name))
        link_header = response.headers.get('Link')
        next_url = None
        if link_header:
            parts = link_header.split(',')
            for part in parts:
                segs = part.split(';')
                if len(segs) >= 2:
                    url_part = segs[0].strip()
                    rel_part = ';'.join(segs[1:]).strip()
                    if 'rel="next"' in rel_part:
                        if url_part.startswith('<') and url_part.endswith('>'):
                            next_url = url_part[1:-1]
                        else:
                            next_url = url_part
                        break
        if not next_url:
            break
        url = next_url
        params = None
    results.sort(key=lambda x: x[0])
    return [name for _, name in results]

